import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as a,c as s,o as e,af as r,b as h,G as d,w as o,a as g,ag as A}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const q=JSON.parse('{"title":"复杂度决策阶梯","description":"需求 → 最低复杂度方案 → 升级触发条件的六级决策表；任何协议介绍之前先读它——协议是选项，不是学习顺序。","frontmatter":{"title":"复杂度决策阶梯","description":"需求 → 最低复杂度方案 → 升级触发条件的六级决策表；任何协议介绍之前先读它——协议是选项，不是学习顺序。","domain":"tech","tags":["tech","orientation","decision"],"navOrder":1,"topicId":"complexity-ladder","layer":"0","status":"canonical","nodeType":"pattern","owner":"learn-ai","externalOwners":[],"prerequisites":["tech-map"],"next":["site-boundaries"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/00-map/complexity-ladder.md","filePath":"zh/tech/00-map/complexity-ladder.md","lastUpdated":1791123418000}'),p={name:"zh/tech/00-map/complexity-ladder.md"};function c(E,t,u,m,b,f){const n=a("Mermaid"),l=a("LadderStepper");return e(),s("div",null,[t[1]||(t[1]=r('<blockquote><p><strong>所在组</strong>：Map · 总览 ｜ <strong>上一组出口</strong>：无 ｜ <strong>本页出口</strong>：能为任一需求选出最低复杂度方案，并说出它的升级触发条件 <strong>前置</strong>：<a href="./../index.html">技术地图</a> ｜ <strong>下一步</strong>：<a href="./site-boundaries.html">站点边界与知识 ownership</a>；准备进入 Context 组的先读<a href="./../03-context/prompt.html">提示词工程</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：面对任何 AI 需求，先在下面的阶梯里找到你的梯级，采用该梯级的<strong>最低复杂度方案</strong>；只有踩中明确的升级触发条件才上一级。这张表先于任何协议介绍——MCP、A2A、ACP、AG-UI 是梯级 6 的候选项，不是学习顺序。</p><h3 id="心智模型-一张梯子" tabindex="-1">心智模型：一张梯子 <a class="header-anchor" href="#心智模型-一张梯子" aria-label="Permalink to &quot;心智模型：一张梯子&quot;">​</a></h3>',4)),(e(),h(A,null,{default:o(()=>[d(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20BT%0A%20%20%20%20R1%5B%22%E6%A2%AF%E7%BA%A7%201%3Cbr%2F%3EPrompt%20%2B%20%E7%BB%93%E6%9E%84%E5%8C%96%E8%BE%93%E5%87%BA%22%5D%20--%3E%7C%E9%9C%80%E8%A6%81%E5%A4%96%E9%83%A8%E4%BA%8B%E5%AE%9E%7C%20R2%5B%22%E6%A2%AF%E7%BA%A7%202%3Cbr%2F%3E%E6%A3%80%E7%B4%A2%20%2F%20RAG%22%5D%0A%20%20%20%20R1%20--%3E%7C%E9%9C%80%E8%A6%81%E4%B8%80%E6%AC%A1%E5%8A%A8%E4%BD%9C%7C%20R3%5B%22%E6%A2%AF%E7%BA%A7%203%3Cbr%2F%3E%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%22%5D%0A%20%20%20%20R2%20--%3E%7C%E9%9C%80%E8%A6%81%E5%A4%9A%E6%AD%A5%E7%BB%84%E5%90%88%7C%20R4%5B%22%E6%A2%AF%E7%BA%A7%204%3Cbr%2F%3E%E5%B7%A5%E4%BD%9C%E6%B5%81%22%5D%0A%20%20%20%20R3%20--%3E%7C%E5%A4%9A%E6%AD%A5%20%C2%B7%20%E5%8F%AF%E6%81%A2%E5%A4%8D%20%C2%B7%20%E9%9C%80%E5%AE%A1%E6%89%B9%7C%20R4%0A%20%20%20%20R4%20--%3E%7C%E8%87%AA%E6%B2%BB%E5%BE%AA%E7%8E%AF%20%2B%20%E6%98%8E%E7%A1%AE%E5%81%9C%E6%AD%A2%E6%9D%A1%E4%BB%B6%7C%20R5%5B%22%E6%A2%AF%E7%BA%A7%205%3Cbr%2F%3EAgent%22%5D%0A%20%20%20%20R5%20--%3E%7C%E8%B7%A8%E4%BF%A1%E4%BB%BB%E5%9F%9F%20%C2%B7%20%E5%BC%82%E6%AD%A5%20%C2%B7%20%E8%83%BD%E5%8A%9B%E5%8F%91%E7%8E%B0%7C%20R6%5B%22%E6%A2%AF%E7%BA%A7%206%3Cbr%2F%3E%E8%BE%B9%E7%95%8C%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>梯子只有一条规则：<strong>默认在最低梯级，让证据把你推上去。</strong> 上行的每一级都新增状态、边界和失败模式；下行的每一级都省掉一类你还没遇到的麻烦。</p><h3 id="六级决策表" tabindex="-1">六级决策表 <a class="header-anchor" href="#六级决策表" aria-label="Permalink to &quot;六级决策表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>梯级</th><th>需求描述</th><th>最低复杂度方案</th><th>升级触发条件</th><th>降级反例</th></tr></thead><tbody><tr><td>1</td><td>固定输入 → 固定输出</td><td>提示词（prompt）+ 结构化输出（structured output）</td><td>需要外部事实或动作</td><td>答案能写进 prompt / 上下文时，不要建检索管线</td></tr><tr><td>2</td><td>需要外部事实</td><td>检索 / RAG（Retrieval-Augmented Generation，检索增强生成）</td><td>数据源多、权限 / 更新 / 延迟成为问题</td><td>知识量小且稳定时，直接放进上下文更便宜</td></tr><tr><td>3</td><td>需要一次受控动作</td><td>函数调用 / 工具调用（tool calling）</td><td>多步、可恢复、需审批 → 梯级 4</td><td>单步操作不需要 agent 循环</td></tr><tr><td>4</td><td>需要多步决策</td><td>工作流（workflow）/ 同域子任务</td><td>需要自治循环和明确停止条件 → 梯级 5</td><td>步骤能静态枚举时，自治循环只增加风险</td></tr><tr><td>5</td><td>需要自治循环</td><td>Agent（运行时 + 停止条件 + 权限边界）</td><td>跨信任域、异步任务、能力发现、跨实现互操作</td><td>任务在同一进程内可完成时，不要跨边界协议</td></tr><tr><td>6</td><td>跨进程 / 组织 / 信任域</td><td>按连接方向选协议（MCP / A2A / ACP / AG-UI）</td><td>—（本阶梯顶）</td><td>同 host 内的工具调用，直接函数 / HTTP 即可</td></tr></tbody></table><h3 id="决策对比表-每级新增了什么" tabindex="-1">决策对比表（每级新增了什么） <a class="header-anchor" href="#决策对比表-每级新增了什么" aria-label="Permalink to &quot;决策对比表（每级新增了什么）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>梯级</th><th>方向</th><th>控制权</th><th>新增状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>1</td><td>读</td><td>你写 prompt，每次调用可改</td><td>无</td><td>进程内</td><td>prompt + 输出 schema</td></tr><tr><td>2</td><td>读</td><td>你控索引与更新节奏</td><td>检索库 + 数据新鲜度</td><td>数据源边界</td><td>retrieval</td></tr><tr><td>3</td><td>写（单次）</td><td>函数边界 + 参数校验</td><td>调用结果与副作用</td><td>进程内</td><td>tool calling</td></tr><tr><td>4</td><td>写（多次）</td><td>流程编排，步骤可静态枚举</td><td>多步状态与中间产物</td><td>进程内</td><td>workflow</td></tr><tr><td>5</td><td>读写循环</td><td>停止条件 + 权限边界</td><td>会话 / 记忆 / checkpoint</td><td>host 内</td><td>agent runtime</td></tr><tr><td>6</td><td>读写跨界</td><td>协议协商 + 能力发现</td><td>任务 / 消息 / artifact</td><td>跨信任域</td><td>边界协议</td></tr></tbody></table><p>「方向」指读世界（read world：检索、引用，默认无副作用）还是写世界（write world：工具、动作，改变外部状态）。写世界的每一级都必须显式处理权限、幂等、取消、重试与回滚。</p><h3 id="何时使用-何时不用" tabindex="-1">何时使用 / 何时不用 <a class="header-anchor" href="#何时使用-何时不用" aria-label="Permalink to &quot;何时使用 / 何时不用&quot;">​</a></h3><ul><li>用：动手前的选型、设计评审、判断「该不该上 agent / 协议」。</li><li>不用：已经确定梯级后的具体实现——去对应层的五段式章节。</li></ul><p>历史版本里程碑：本阶梯于 2026-09 随 Issue #116 冻结，整合自旧版「训练决策树」与「workflow vs agent」讨论；更早来源未验证，不编造。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是决策工具，无可运行代码产物；「使用」= 决策演练（纸面即可，≤15 分钟）。验收标准：四个场景全部选中「最低复杂度方案 + 能说出为什么不上更高梯级」。</p><h3 id="演练-四个场景" tabindex="-1">演练：四个场景 <a class="header-anchor" href="#演练-四个场景" aria-label="Permalink to &quot;演练：四个场景&quot;">​</a></h3><p>对每个场景，先自己选梯级，再对照预期输出。</p><p><strong>场景 A</strong>：把客服邮件分成三类并给出置信度。</p><ul><li>预期：梯级 1。固定输入 → 固定输出，prompt + 输出 schema 足够。</li><li>反例判断：不需要外部事实（不查工单库）、不需要动作（不改工单状态），无升级触发条件。</li></ul><p><strong>场景 B</strong>：问答必须基于公司内部 8000 篇 wiki。</p><ul><li>预期：梯级 2。外部事实超出上下文预算，走检索 / RAG。</li><li>反例判断：如果只有 20 篇且每季更新，塞进上下文（梯级 1 + 长上下文）更便宜。</li></ul><p><strong>场景 C</strong>：用户确认后，把报销单写入审批系统。</p><ul><li>预期：梯级 3。一次受控动作：工具调用 + 参数校验 + 权限边界。</li><li>反例判断：不需要模型决定「先查额度再写入再通知」的链条；若需要，才升梯级 4。</li></ul><p><strong>场景 D</strong>：研究助手自己读文献、交叉验证、写综述，何时停由它判断。</p><ul><li>预期：梯级 5。自治循环成立的前提是你能写出<strong>明确停止条件</strong>（页数上限、时间上限、验证通过）和<strong>权限边界</strong>（只读沙箱）。</li><li>反例判断：如果步骤其实是「检索 → 摘要 → 汇总」的固定链，那是梯级 4 的工作流，不需要自治。</li></ul><h3 id="使用边界" tabindex="-1">使用边界 <a class="header-anchor" href="#使用边界" aria-label="Permalink to &quot;使用边界&quot;">​</a></h3><ul><li>本阶梯判断的是<strong>系统形态</strong>，不是模型能力：同一个模型可以服务所有梯级。</li><li>梯级之间可以组合（一个 agent 内部调用 RAG），但对外呈现的形态仍取最高涉及梯级，风险预算按该梯级评估。</li></ul>',23)),d(l),t[3]||(t[3]=r('<h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么默认最低梯级" tabindex="-1">为什么默认最低梯级 <a class="header-anchor" href="#为什么默认最低梯级" aria-label="Permalink to &quot;为什么默认最低梯级&quot;">​</a></h3><p>每一级升级都在三类成本上单调递增：</p><ol><li><strong>状态</strong>：梯级 1 无状态；梯级 2 有检索库与新鲜度；梯级 4 有多步中间产物；梯级 5 有会话、记忆与 checkpoint。状态越多，恢复与调试越贵。</li><li><strong>边界</strong>：从进程内到数据源边界，再到跨信任域。每多一个边界，就多一类授权、版本与协议协商问题。</li><li><strong>失败模式</strong>：梯级 1 失败是「输出不合 schema」，可当场重试；梯级 5 失败可能是「已经执行了三步副作用」，需要补偿与回滚。</li></ol><p>低梯级方案的失败是<strong>局部的、可重放的</strong>；高梯级方案的失败是<strong>分布式的、有副作用的</strong>。这就是「证据推你上行」的原因：没有踩中触发条件就上行，你提前支付了还没有问题的那部分复杂度。</p><h3 id="读世界-写世界是横切不变量" tabindex="-1">读世界 / 写世界是横切不变量 <a class="header-anchor" href="#读世界-写世界是横切不变量" aria-label="Permalink to &quot;读世界 / 写世界是横切不变量&quot;">​</a></h3><p>梯级 1–2 基本在读世界：提供证据，默认无副作用。梯级 3 起进入写世界：改变外部状态，必须显式处理权限、幂等、取消、重试、人工批准与回滚。这些不是某一级的专属话题，而是从梯级 3 起每一级都要回答的问题——行动、Agent 系统与生产各组的章节会反复回到这张清单。</p><h3 id="为什么协议在梯顶" tabindex="-1">为什么协议在梯顶 <a class="header-anchor" href="#为什么协议在梯顶" aria-label="Permalink to &quot;为什么协议在梯顶&quot;">​</a></h3><p>协议（梯级 6）解决的是「跨信任域的通信与能力发现」，它引入的不只是技术成本，还有组织成本：版本协商、安全边界、互操作性承诺。只有存在独立信任域、异步任务、能力发现或跨实现互操作需求时，协议才是正确选项。同一 host 内的工具接入，用直接函数调用或普通 HTTP 就够。</p><h3 id="规范要求-vs-本地实测" tabindex="-1">规范要求 vs 本地实测 <a class="header-anchor" href="#规范要求-vs-本地实测" aria-label="Permalink to &quot;规范要求 vs 本地实测&quot;">​</a></h3><p>本页是决策模式，无规范可实现测。各梯级方案的「规范 vs 实测」分栏见对应层章节：结构化输出与模型 API（推理与接口组）、RAG（知识接地组）、工具执行（行动组）、协议（互操作组）。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>本页无代码集成；「开发」= 把阶梯用作设计与评审的门禁。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：系统随机失败、难调试，没人能说清一次请求经过了哪些组件。 <strong>证据</strong>：架构图里出现 agent / 协议，但需求描述落在梯级 1–3；trace 里大量与任务无关的循环步骤。 <strong>处理</strong>：按本表降级到满足验收的最低梯级；把被砍掉的能力列为显式待办（等触发条件出现再升级）。 <strong>完成标准</strong>：设计文档标注当前梯级、已核对的升级触发条件、以及「哪些触发条件已出现」的证据。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：团队争论「该不该上 agent」，各执一词。 <strong>证据</strong>：双方都写不出自治循环的<strong>停止条件</strong>与<strong>权限边界</strong>——这两个字段为空说明梯级 5 的准入条件不满足。 <strong>处理</strong>：先按梯级 4 工作流实现，把「步骤无法静态枚举」的案例收集起来作为升级证据。 <strong>完成标准</strong>：要么静态步骤清单跑通（留在梯级 4），要么攒到「枚举失败」的真实案例再升级。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：评审要求引入 MCP / A2A「以备将来对接」。 <strong>证据</strong>：当前所有协作都在同一 host / 进程内；没有第二个信任域、没有异步任务、没有能力发现需求。 <strong>处理</strong>：引用梯级 6 的升级触发条件逐条对照，全部未命中则改用进程内方案。 <strong>完成标准</strong>：设计文档写明「若未来出现 X（跨信任域 / 异步 / 能力发现），再引入协议 Y」。</p><h3 id="反模式清单" tabindex="-1">反模式清单 <a class="header-anchor" href="#反模式清单" aria-label="Permalink to &quot;反模式清单&quot;">​</a></h3><ul><li><strong>名词驱动架构</strong>：先选定热门协议 / 框架，再回头找能用它的场景。</li><li><strong>跳级</strong>：跳过输出 schema 与失败验收（梯级 1 的功课）直接上 agent——所有上层故障都会变成「模型不行」。</li><li><strong>把 demo 当验收</strong>：演示跑通 ≠ 停止条件、权限边界、回滚路径存在。这是「看似成功但证据不足」的典型路径。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：读本页 + <a href="./../index.html">技术地图</a>的决策树；能复述六级与各自触发条件。</li><li><strong>Builder</strong>：进 <a href="./../03-context/">Context 组</a>，把梯级 1 做扎实（prompt + schema + 失败验收）。</li><li><strong>Operator</strong>：进 <a href="./../06-agent-systems/agent-runtime.html">Agent 系统组</a> 与 <a href="./../08-production/">Production 组</a>，学习梯级 3–5 的权限、幂等与回滚。</li><li><strong>Researcher</strong>：读下面 L1 级资料，理解业界对「workflow vs agent」边界的论证。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>证据层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Building Effective Agents（Anthropic）</td><td>L1（维护者）</td><td><a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">https://www.anthropic.com/research/building-effective-agents</a></td><td>workflow 与 agent 的边界、从简单组合开始的论证</td><td>「先组合后升级」的工程口径（retrievedAt 2026-09-01，HTTP 200）</td><td>对照本页梯级 4 / 5</td></tr><tr><td>MCP 官网</td><td>L0（官方规范）</td><td><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/</a></td><td>梯级 6 候选项之一：Agent ↔ 工具 / 数据边界</td><td>协议解决边界通信（retrievedAt 2026-09-01，HTTP 200）</td><td><a href="./../07-interoperability/mcp.html">MCP 章</a></td></tr><tr><td>A2A 官网</td><td>L0（官方规范）</td><td><a href="https://a2a-protocol.org/" target="_blank" rel="noreferrer">https://a2a-protocol.org/</a></td><td>梯级 6 候选项之一：跨信任域 Agent 协作</td><td>跨信任域才需要远程协作协议（retrievedAt 2026-09-01，HTTP 200）</td><td><a href="./../07-interoperability/a2a.html">A2A 章</a></td></tr><tr><td>Learn LLM 第 11 章（RAG）</td><td>sibling</td><td><a href="https://llm.zenheart.site/chapters/11-rag" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/11-rag</a></td><td>梯级 2 的底层原理（何时检索有效）</td><td>检索原理归 Learn LLM（retrievedAt 2026-09-01，HTTP 200）</td><td>本仓<a href="./../04-grounding/">知识接地组</a></td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你找到了一个场景——梯级 N 的最低方案无法满足验收、且梯级 N-1 的触发条件未命中——本阶梯存在漏洞，应修订触发条件而不是掩盖场景。</li><li>未决：梯级 6 的「按连接方向选协议」细则（MCP / A2A / ACP / AG-UI 各自匹配的边界）在互操作组协议地图落地，本页只保留判断框架。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>各梯级的实现细节：本仓各组对应章节。</li><li>梯级 2 / 5 的底层原理（检索数学、训练对行为的影响）：<a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。</li><li>证明每一级「做到位了」的评估方法：<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>。</li></ul>',30))])}const x=i(p,[["render",c]]);export{q as __pageData,x as default};
